initJs:
function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let timerInterval = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;

  // 現在日時更新
  function updateCurrentTime() {
    const now = new Date();
    container.querySelector('#current-datetime').textContent = 
      now.toLocaleDateString('ja-JP') + ' ' + now.toLocaleTimeString('ja-JP');
  }
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);

  // 作業項目選択肢を設定
  function loadWorkItems() {
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    if (workItemsTable) {
      const select = container.querySelector('#work-item-select');
      select.innerHTML = '<option value="">選択してください</option>';
      workItemsTable.records.forEach(item => {
        if (item.有効フラグ) {
          select.innerHTML += `<option value="${item.作業項目ID}">${item.作業項目名}</option>`;
        }
      });
    }
  }

  // 経過時間表示更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;
    if (pauseStartTime) {
      elapsed -= (now - pauseStartTime);
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    container.querySelector('#elapsed-time').textContent = 
      `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  }

  // 本日の作業履歴を描画
  function renderTodayWorkList(records) {
    const tbody = container.querySelector('#today-work-list');
    const today = new Date().toDateString();
    const todayRecords = records.filter(r => new Date(r.作業日).toDateString() === today);

    tbody.innerHTML = todayRecords.map(record => {
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}h${record.作業時間 % 60}m` : '';

      return `
        <tr data-id="${record.作業記録ID}">
          <td>${startTime}</td>
          <td>${endTime}</td>
          <td>${workTime}</td>
          <td>${record.作業種別 || ''}</td>
          <td>${record.作業場所 || ''}</td>
          <td>
            <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; 
              ${record.進捗状況 === '作業中' ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 
                record.進捗状況 === '完了' ? 'background: rgba(59, 130, 246, 0.2); color: #3b82f6;' : 
                'background: rgba(239, 68, 68, 0.2); color: #ef4444;'}">
              ${record.進捗状況 || ''}
            </span>
          </td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 2px 6px; margin-right: 4px;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 2px 6px;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ読み込み
  loadWorkItems();
  const workRecordsTableIndex = tables.findIndex(t => t.tableName === '作業記録');
  if (workRecordsTableIndex >= 0) {
    renderTodayWorkList(tables[workRecordsTableIndex].records || []);

    // 最新データを取得
    window.aivicApi.list(workRecordsTableIndex).then(records => {
      if (records) renderTodayWorkList(records);
    });
  }

  // 作業開始
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location').value;

    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }
    if (!workLocation) {
      alert('作業場所を入力してください');
      return;
    }

    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    const selectedItem = workItemsTable.records.find(item => item.作業項目ID === workItemId);

    const newRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証済みユーザーIDを使用
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      プロジェクト名: selectedItem?.作業項目名|| '',
      作業場所: workLocation,
      作業種別: selectedItem?.作業項目名|| '',
      作業内容: '',
      進捗状況: '作業中',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(workRecordsTableIndex, newRecord);
    if (saved) {
      currentWorkRecord = saved;
      startTime = new Date();
      totalPauseTime = 0;
      pauseStartTime = null;

      // ボタン状態更新
      container.querySelector('#btn-start-work').disabled = true;
      container.querySelector('#btn-end-work').disabled = false;
      container.querySelector('#btn-pause-work').disabled = false;

      // タイマー開始
      timerInterval = setInterval(updateElapsedTime, 1000);

      // 履歴更新
      const records = await window.aivicApi.list(workRecordsTableIndex);
      if (records) renderTodayWorkList(records);
    }
  });

  // 作業終了
  container.querySelector('#btn-end-work').addEventListener('click', async () => {
    if (!currentWorkRecord) return;

    const workMemo = container.querySelector('#work-memo').value;
    const endTime = new Date();
    const workTimeMinutes = Math.floor((endTime - startTime - totalPauseTime) / (1000 * 60));

    const updated = await window.aivicApi.update(workRecordsTableIndex, currentWorkRecord.作業記録ID || currentWorkRecord.id, {
      作業終了時刻: endTime.toISOString(),
      作業時間: workTimeMinutes,
      作業内容: workMemo,
      進捗状況: '完了'
    });

    if (updated) {
      // 状態リセット
      currentWorkRecord = null;
      startTime = null;
      totalPauseTime = 0;
      pauseStartTime = null;
      clearInterval(timerInterval);

      // ボタン状態更新
      container.querySelector('#btn-start-work').disabled = false;
      container.querySelector('#btn-end-work').disabled = true;
      container.querySelector('#btn-pause-work').disabled = true;
      container.querySelector('#elapsed-time').textContent = '00:00:00';

      // フォームクリア
      container.querySelector('#work-item-select').value = '';
      container.querySelector('#work-location').value = '';
      container.querySelector('#work-memo').value = '';

      // 履歴更新
      const records = await window.aivicApi.list(workRecordsTableIndex);
      if (records) renderTodayWorkList(records);
    }
  });

  // 作業中断
  container.querySelector('#btn-pause-work').addEventListener('click', () => {
    pauseStartTime = new Date();
    container.querySelector('#pause-reason-area').style.display = 'block';
    container.querySelector('#btn-pause-work').disabled = true;
  });

  // 作業再開
  container.querySelector('#btn-resume-work').addEventListener('click', async () => {
    const reasonCategory = container.querySelector('#pause-reason-category').value;
    const reasonDetail = container.querySelector('#pause-reason-detail').value;

    if (!reasonCategory) {
      alert('中断理由区分を選択してください');
      return;
    }

    if (pauseStartTime) {
      const pauseEndTime = new Date();
      const pauseDuration = pauseEndTime - pauseStartTime;
      totalPauseTime += pauseDuration;

      // 中断記録を保存
      const pauseRecordsTableIndex = tables.findIndex(t => t.tableName === '中断記録');
      if (pauseRecordsTableIndex >= 0) {
        await window.aivicApi.save(pauseRecordsTableIndex, {
          作業記録ID: currentWorkRecord.作業記録ID || currentWorkRecord.id,
          中断開始日時: pauseStartTime.toISOString(),
          中断終了日時: pauseEndTime.toISOString(),
          中断理由区分: reasonCategory,
          中断理由詳細: reasonDetail,
          中断時間: Math.floor(pauseDuration / (1000 * 60)),
          対応状況: '解決済み',
          記録者ID: 'current-user-id'
        });
      }
    }

    pauseStartTime = null;
    container.querySelector('#pause-reason-area').style.display = 'none';
    container.querySelector('#btn-pause-work').disabled = false;
    container.querySelector('#pause-reason-category').value = '';
    container.querySelector('#pause-reason-detail').value = '';
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#work-memo').value = '';
  });

  // 保存ボタン（作業中の内容更新）
  container.querySelector('#btn-save-work').addEventListener('click', async () => {
    if (!currentWorkRecord) {
      alert('作業が開始されていません');
      return;
    }

    const workMemo = container.querySelector('#work-memo').value;
    const updated = await window.aivicApi.update(workRecordsTableIndex, currentWorkRecord.作業記録ID || currentWorkRecord.id, {
      作業内容: workMemo
    });

    if (updated) {
      alert('作業内容を保存しました');
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この作業記録を削除しますか？')) return;

      await window.aivicApi.delete(workRecordsTableIndex, deleteBtn.dataset.id);
      const records = await window.aivicApi.list(workRecordsTableIndex);
      if (records) renderTodayWorkList(records);
      return;
    }

    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      // 編集機能は簡略化（実際の実装では編集フォームを表示）
      alert('編集機能は作業履歴画面で行ってください');
    }
  });
}
